function maxOperations(nums) {
  const n = nums.length;

  function mostOperations(score) {
    // shorter[left]: most operations on the window two elements shorter that starts at left.
    let shorter = new Array(n + 1).fill(0);
    for (let len = 2 + (n % 2); len <= n; len += 2) {
      const current = new Array(n - len + 1).fill(0);
      for (let left = 0; left + len <= n; left++) {
        const right = left + len - 1;
        let best = 0;
        if (nums[left] + nums[left + 1] === score) {
          best = Math.max(best, 1 + shorter[left + 2]);
        }
        if (nums[right - 1] + nums[right] === score) {
          best = Math.max(best, 1 + shorter[left]);
        }
        if (nums[left] + nums[right] === score) {
          best = Math.max(best, 1 + shorter[left + 1]);
        }
        current[left] = best;
      }
      shorter = current;
    }
    return shorter[0];
  }

  let answer = 0;
  const firstScores = [nums[0] + nums[1], nums[n - 2] + nums[n - 1], nums[0] + nums[n - 1]];
  for (const score of new Set(firstScores)) {
    answer = Math.max(answer, mostOperations(score));
  }
  return answer;
}

