function maxOperations(nums) {
  // Try every sequence of operations; the first one fixes the score.
  const explore = (items, score) => {
    if (items.length < 2) return 0;
    const last = items.length - 1;
    const moves = [
      [items[0] + items[1], items.slice(2)],
      [items[last - 1] + items[last], items.slice(0, last - 1)],
      [items[0] + items[last], items.slice(1, last)],
    ];
    let most = 0;
    for (const [sum, rest] of moves) {
      if (score === null || sum === score) most = Math.max(most, 1 + explore(rest, sum));
    }
    return most;
  };
  return explore(nums, null);
}

