function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(1990, 2000) : int(2, 11);
  const mode = int(0, 2);
  if (mode === 0) {
    // Few distinct values: many equal sums and many competing choices.
    const top = size === 'large' ? int(2, 4) : int(1, 4);
    return [Array.from({ length: n }, () => int(1, top))];
  }
  // Build the array by undoing random operations that all share one score, then maybe break a few spots.
  const score = int(2, 2000);
  const pair = () => { const a = int(Math.max(1, score - 1000), Math.min(1000, score - 1)); return [a, score - a]; };
  let items = n % 2 ? [int(1, 1000)] : [];
  while (items.length < n) {
    const [a, b] = pair();
    const kind = int(0, 2);
    if (kind === 0) items = [a, b, ...items];
    else if (kind === 1) items = [...items, a, b];
    else items = [a, ...items, b];
  }
  if (mode === 2) {
    const breaks = size === 'large' ? int(1, 6) : 1;
    for (let i = 0; i < breaks; i++) items[int(0, n - 1)] = int(1, 1000);
  }
  return [items];
}
